import{_ as t,o,c as a,a2 as r}from"./chunks/framework.Crpw6aS5.js";const b=JSON.parse('{"title":"2019年 · 留存收益的力量","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/2019年.md","filePath":"05_quotes/by-year/2019年.md"}'),l={name:"05_quotes/by-year/2019年.md"};function u(c,e,q,p,s,_){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_2019年-·-留存收益的力量" tabindex="-1">2019年 · 留存收益的力量 <a class="header-anchor" href="#_2019年-·-留存收益的力量" aria-label="Permalink to &quot;2019年 · 留存收益的力量&quot;">​</a></h1><blockquote><p>管理良好的工业企业通常不会将全部利润分配给股东。在好的年份，它们会保留一部分利润并重新投入业务。因此，存在一个复利因素有利于稳健的工业投资。——巴菲特（89岁）</p></blockquote><p>本页收录2019年致股东信中的经典语录。本年以留存收益的复利力量为核心论述，引用埃德加·劳伦斯·史密斯1924年的开创性著作，同时深入探讨了公司治理的改革议题。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>留存收益的数学原理现在已被充分理解。今天，学童们都能学到凯恩斯所说的&quot;新颖&quot;观点：将储蓄与复利结合，会创造奇迹。</p></blockquote><blockquote><p>在伯克希尔的前十大持仓中，被投资公司为我们保留的收益约为83亿美元，而我们收到的股息约为38亿美元。这些留存收益肯定对伯克希尔价值的增长具有重大意义。史密斯先生说得对。</p></blockquote><blockquote><p>收购类似于婚姻：它们当然以欢乐的婚礼开始——但现实往往与婚前预期背道而驰。</p></blockquote><blockquote><p>当一家公司聘请两位&quot;专家&quot;收购顾问，一位支持，一位反对，向董事会发表他或她对拟议交易的看法——获胜的顾问将获得十倍于支付给失败者的象征性金额——这将是一个有趣的练习。不要屏息等待这一改革：不要问理发师你是否需要理发。</p></blockquote><blockquote><p>我们希望跨境投资大量资金。然而，在未来77年，我们收益的主要来源几乎肯定将由&quot;美国顺风&quot;提供。我们很幸运——非常幸运——有这种力量在我们身后。</p></blockquote><blockquote><p>查理和我有非常务实的原因希望确保伯克希尔在我们退出后的岁月里繁荣昌盛：芒格家族持有的伯克希尔股份远超该家族任何其他投资，而我99%的净资产都存放在伯克希尔股票中。我从未出售过任何股份，也没有计划这样做。</p></blockquote><blockquote><p>在伯克希尔，我们的受众既不是分析师也不是评论员：查理和我是为我们的股东合伙人工作的。流向我们的数字就是我们传递给你们的数字。</p></blockquote><blockquote><p>明天股票价格可能发生任何事情。偶尔，市场会出现大幅下跌，可能达到50%甚至更大的幅度。但是，&quot;美国顺风&quot;和史密斯先生描述的复利奇迹的结合，将使股票成为不使用借来的钱且能够控制自己情绪的个人更好的长期选择。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>2019年伯克希尔每股市场价值增长11.0%，但大幅落后于标普500的31.5%。GAAP净利润达814亿美元（含537亿未实现收益），但营业利润仅240亿美元与上年持平。本年信首次引用1924年史密斯著作论述留存收益的力量，并首次将业绩表从账面价值完全切换为市场价格。董事会治理议题获得深入讨论，股东大会形式迎来重大变革——阿吉特·贾因和格雷格·阿贝尔将更多参与问答。浮存金增至1294亿美元历史新高。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><p><a href="/01_letters/2019年/翻译.html">01_letters/2019年/翻译</a> · <a href="/01_letters/2019年/核心总结.html">01_letters/2019年/核心总结</a> · <a href="/01_letters/2019年/思维导图.html">01_letters/2019年/思维导图</a></p>',19)])])}const n=t(l,[["render",u]]);export{b as __pageData,n as default};
